self.addEventListener('install', (event) => {
  self.skipWaiting();
  event.waitUntil(
    caches.open(CACHE).then(async (cache) => {
      // aggiunge a gruppi per non fallire tutto per un singolo file
      const chunks = [];
      for (let i = 0; i < ASSETS.length; i += 25) chunks.push(ASSETS.slice(i, i + 25));
      for (const chunk of chunks) {
        await Promise.allSettled(chunk.map((url) => cache.add(new Request(url, { cache: 'reload' }))));
      }
    })
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;
  // range requests (video) -> risposta parziale dalla cache
  if (req.headers.has('range')) {
    event.respondWith(rangeFromCache(req));
    return;
  }
  const isPage = req.mode === 'navigate' || (req.headers.get('accept') || '').includes('text/html');
  const isHashed = url.pathname.includes('/_astro/');

  // Pagine: prima la rete (versione sempre aggiornata quando c'è connessione), poi la cache (offline).
  if (isPage) {
    event.respondWith(
      fetch(req)
        .then((res) => {
          if (res.ok) caches.open(CACHE).then((c) => c.put(req, res.clone()));
          return res;
        })
        .catch(() => caches.match(req, { ignoreSearch: true }).then((hit) => hit || caches.match(BASE, { ignoreSearch: true })))
    );
    return;
  }

  // Asset con hash nel nome (_astro/*): immutabili, cache prima.
  if (isHashed) {
    event.respondWith(
      caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req).then((res) => {
        if (res.ok) caches.open(CACHE).then((c) => c.put(req, res.clone()));
        return res;
      }))
    );
    return;
  }

  // Tutto il resto (manifest, icone, media): cache subito, aggiornamento in background.
  event.respondWith(
    caches.match(req, { ignoreSearch: true }).then((hit) => {
      const refresh = fetch(req)
        .then((res) => {
          if (res.ok) caches.open(CACHE).then((c) => c.put(req, res.clone()));
          return res;
        })
        .catch(() => hit || Response.error());
      return hit || refresh;
    })
  );
});

async function rangeFromCache(req) {
  const cached = await caches.match(req.url, { ignoreSearch: true });
  if (!cached) return fetch(req);
  const buf = await cached.arrayBuffer();
  const m = /bytes=(\d+)-(\d*)/.exec(req.headers.get('range') || '');
  const start = m ? Number(m[1]) : 0;
  const end = m && m[2] ? Number(m[2]) : buf.byteLength - 1;
  const slice = buf.slice(start, end + 1);
  return new Response(slice, {
    status: 206,
    statusText: 'Partial Content',
    headers: {
      'Content-Type': cached.headers.get('Content-Type') || 'application/octet-stream',
      'Content-Range': 'bytes ' + start + '-' + end + '/' + buf.byteLength,
      'Content-Length': String(slice.byteLength),
      'Accept-Ranges': 'bytes',
    },
  });
}
